def is_samepatterns(strs, patterns):
    # Create a dictionary to map each string to a unique pattern
    d = {}
    # Iterate over the patterns and strings simultaneously
    for i, j in zip(patterns, strs):
        # Check if the pattern already exists in the dictionary
        if i in d:
            # If the current string does not match the stored string for this pattern, return False
            if d[i] != j:
                return False
        else:
            # If the pattern does not exist, add it to the dictionary with the current string
            d[i] = j
    # If all patterns match their corresponding strings, return True
    return True

