def sequential_search(arr, e):
    found = False
    index = 0
    n = len(arr)
    # Loop through the array to find the element
    while index < n and not found:
        if arr[index] == e:
            found = True
        else:
            index += 1
    # Return a tuple with the result and the index
    return (found, index if found else -1)

