def jacobsthal_num(n): 
    # Base case: return n if n is 0 or 1
    if n <= 1: 
        return n 
    # Recursive case: calculate the nth Jacobsthal number
    return jacobsthal_num(n - 1) + 2 * jacobsthal_num(n - 2) 

